pub fn funcs(out: &mut Vec<(u32, crate::AbiFn)>) {
    d3dx9::funcs(out);
    fallout_audio::funcs(out);
    fallout_debug::funcs(out);
    fallout_misc::funcs(out);
    fallout_shared_settings::funcs(out);
    remotelog::funcs(out);
    unplaced::funcs(out);
    xapilib::funcs(out);
}

